import json
import math
import statistics as st

dates = ["2024-03-01", "2024-03-04", "2024-03-05", "2024-03-06", "2024-03-07", "2024-03-08"]
closes = {
    "ACME": [100.0, 102.0, 99.0, 97.5, 101.0, 103.0],
    "GLOBEX": [50.0, 50.5, 51.0, 51.2, 51.8, 52.4],
}
rets = {t: [math.log(c[i] / c[i - 1]) for i in range(1, 6)] for t, c in closes.items()}
print("returns", json.dumps(rets))
w = 2
vol = {
    t: [None if i < w else st.stdev(r[i - w : i]) * math.sqrt(252) for i in range(5)]
    for t, r in rets.items()
}
print("vol", json.dumps(vol))
for t in rets:
    r = rets[t]
    ar = 252 * st.mean(r)
    av = math.sqrt(252) * st.stdev(r)
    print("summary", t, json.dumps(dict(ann_return=ar, ann_vol=av, sharpe=ar / av, last_vol=vol[t][-1])))
for t, rr in rets.items():
    peak = 1.0
    pd = dates[0]
    best = (0.0, dates[0], dates[0])
    s = 0.0
    for d, x in zip(dates[1:], rr):
        s += x
        wealth = math.exp(s)
        if wealth > peak:
            peak = wealth
            pd = d
        dd = wealth / peak - 1
        if dd < best[0]:
            best = (dd, pd, d)
    print("drawdown", t, best)

